  const repeat=this.field(form,'repeat','Ricorrenza','',value.repeat,[['none','Mai'],['daily','Ogni giorno'],['weekdays','Giorni feriali'],['weekly','Ogni settimana'],['monthly','Ogni mese'],['yearly','Ogni anno']]);
  const interval=this.field(form,'interval','Intervallo','number',value.interval);interval.min=1;interval.max=99;
  const until=this.field(form,'until','Fine ricorrenza (facoltativa)','datetime-local',value.until?localDate(value.until):'');
  repeat.onchange=()=>{const hidden=repeat.value==='none';for(const input of [interval,until]){input.disabled=hidden;input.hidden=hidden;input.previousElementSibling.hidden=hidden;}interval.previousElementSibling.textContent=tr('Ogni')+' ('+tr(({daily:'giorni',weekdays:'giorni feriali',weekly:'settimane',monthly:'mesi',yearly:'anni'})[repeat.value]||'giorni')+')';};repeat.onchange();
  const message=el('p','','reminder-status');message.setAttribute('role','alert');form.append(message);
  const commit=async(next,remove=false)=>{const rs=(n.reminders||[]).filter(x=>x.id!==value.id);if(!remove)rs.push(next);const range=this.index.notes.get(n.id)?.markers.get(value.id);this.h.commit(n,normalizeReminders(rs),remove?(range?{...range,text:''}:null):{from:range?.from??selection[0],to:range?.to??selection[1],text:reminderLink(next)});await this.h.flush();this.h.close();if(this.auth)await this.sync();else this.h.report(Error(tr('Accedi per attivare le notifiche dei reminder.')));};
  const actions=el('div','','buttons');const save=el('button',tr('Salva'),'primary');save.type='submit';actions.append(save,this.button(tr('Annulla'),()=>this.h.close()));form.append(actions);
