  if(!isNew){const extra=el('div','','reminder-actions');extra.append(this.button(tr(value.done?'Riapri':value.repeat==='none'?'Completa':'Termina ricorrenza'),()=>commit({...value,done:!value.done})),this.button(tr('Posticipa 10 minuti'),()=>commit({...value,done:false,snooze:new Date(Date.now()+600000).toISOString()})),this.button(tr('Elimina'),()=>{if(confirm(tr('Rimuovere questo reminder?')))return commit(value,true);}));form.append(extra);}
